const r = await fetch("https://repo.jcrabapple.com/jcrabapple/82208449e52b434a8e695c8124fa3f79/raw/HEAD/kagi-catppuccin-mocha.css");
const t = await r.text();
const lines = t.split("\n");
console.log("lines", lines.length, "bytes", t.length);
console.log(lines.slice(0, 40).join("\n"));
console.log("---- structure (non-variable lines) ----");
lines.forEach((l,i)=>{ if(!/^\s*--[\w-]+:/.test(l) && l.trim()) console.log(i+1, l.slice(0,110)); });
const r2 = await fetch("https://repo.jcrabapple.com/jcrabapple/82208449e52b434a8e695c8124fa3f79");
const h = await r2.text();
console.log("---- files in gist ----");
console.log([...h.matchAll(/data-filename="([^"]+)"/g)].map(m=>m[1]).filter((v,i,a)=>a.indexOf(v)===i));
