import re

import pytest

from build_theme import PALETTES, contrast, convert, mix

FIXTURE = """\
:root {
  --text: #4c4f69;
  --base: #eff1f5;
  --mauve: #8839ef;
  --dd-hover-bg: var(--mauve);
  --dd-hover-color: var(--text);
}

.theme_moon_dark {
  --text: #cdd6f4;
  --base: #1e1e2e;
  --mauve: #cba6f7;
}
"""

