.theme_moon_dark {
  --text: #cdd6f4;
  --base: #1e1e2e;
  --mauve: #cba6f7;
}
"""

DROPDOWN_HOVER = (
    ".filter-item.dropdown:not(.filter_item_icon, .filter_item_single)"
    ":is(:focus-within, :hover)"
)

VAR = re.compile(r"var\(--([\w-]+)\)")
COLOR_MIX = re.compile(
    r"color-mix\(in srgb, var\(--([\w-]+)\) (\d+)%, var\(--([\w-]+)\)\)"
)


