    if match := VAR.fullmatch(value):
        return palette[match.group(1)]
    if match := COLOR_MIX.fullmatch(value):
        top, percent, bottom = match.groups()
        return mix(palette[bottom], palette[top], int(percent) / 100)
    raise ValueError(value)


