import re, sys, pathlib, difflib
sys.path.insert(0, "/Users/rod/x/kagi-selenized")
import build_theme as b
root = pathlib.Path("/Users/rod/x/kagi-selenized/reference")
new = (root / "github/custom.css").read_text(encoding="utf-8")
old = (root / "gist/kagi-catppuccin-mocha.css").read_text(encoding="utf-8")

print("== does convert() run on the new input unchanged? ==")
try:
    out = b.convert(new)
    print("yes, output", len(out), "bytes")
except Exception as e:
    print("NO:", type(e).__name__, e)
    out = None

print("\n== what changed upstream (old gist -> new repo file), excluding pure renames ==")
ol, nl = old.split("\n"), new.split("\n")
sm = difflib.SequenceMatcher(None, ol, nl, autojunk=False)
shown = 0
for tag, i1, i2, j1, j2 in sm.get_opcodes():
    if tag == "equal": continue
    shown += 1
    print(f"--- {tag} old[{i1+1}:{i2}] new[{j1+1}:{j2}]")
    for l in ol[i1:i2][:6]: print("  - " + l[:110])
    for l in nl[j1:j2][:8]: print("  + " + l[:110])
    if shown >= 40: print("... more"); break
print("total change blocks:", sum(1 for t,*_ in sm.get_opcodes() if t != "equal"))
