743	  color: var(--bg-1) !important;
744	}
745	
746	/* Search Results */
747	.search-result,
748	.sri-group {
749	  border-bottom: unset !important;
750	}
751	.inline-content + .search-result,
752	.inline-content + .sri-group {
753	  border-top: unset !important;
754	}
755	.s-f-w.--active .search_area {
756	  padding: 10px !important;
757	}
758	.main-center-box > * {
759	  margin-inline: auto;
760	  max-width: 850px;
761	  padding-inline: 16px;
762	  width: 100%;
763	}
764	.__sri-title .__sri_title_link {
765	  border-bottom: 0;
766	}
767	
768	/* Background Crust Overrides */
769	#thread-sidebar-visible:checked ~ #sidebar-backdrop,
770	.quick-settings,
771	.quick-settings-footer,
772	.promptOptionsSelector,
773	.promptOptionsSelector .search-bar,
774	.k_ui_dropdown_data_list,
775	._0_more_search_box,
776	.dropdown .dd-list,
777	.chat_bubble .actions,
778	.citation,
779	.message-info,
780	.thread-more-menu,
781	.threads-pane {
782	  background-color: var(--bg-1) !important;
783	}
784	
785	/* Lenses */
786	._0_lenses {
787	  background-color: unset !important;
788	}
789	
790	/* Mobile Internet Access */
791	#internet-access-mobile:has(:checked) {
792	  color: var(--bg-2);
793	}
794	
795	/* Team Badge */
796	.team_badge {
797	  color: var(--bg-1);
798	}
799	
800	/* Image Preview */
801	#PreviewImageViewImageBtn,
802	#PreviewImageViewPageBtn {
803	  color: unset !important;
804	}
805	
806	/* Media Queries */
807	@media (min-width: 1280px) {
808	  #promptBox:placeholder-shown + .rich-placeholder {
809	    padding-left: 25px;
810	  }
811	}
812	
813	@media all and (min-device-width: 766px) {
814	  form#form {
815	    margin: 0;
816	    border: 1px var(--orange) solid;
817	    border-radius: 35px;
818	    padding: 12px 20px;
819	  }
820	  ._0_more_search_box {
821	    max-width: 300px;
822	    width: unset;
823	  }
824	  .app-content-box { /* the element was header.app-header.app-content-box */
825	  max-width: none;
826	  }
827	}
828	
829	@media all and (max-device-width: 766px) {
830	  .cluster section.did-you-know {
831	    background-color: var(--box-shadow-15);
832	  }
833	  .cluster section.perspectives ul li {
834	    background-color: var(--ai_chat_buble_a_bg);
835	  }
836	  .cluster .cluster-header .badge {
837	    background-color: var(--accent-info);
838	  }
839	  .bg-p-50 {
840	    background-color: var(--bg-2);
841	  }
842	  body:not(._0_processing) #form:has(#promptBox:placeholder-shown):has(#uploadedItems:empty) #submit {
843	    color: var(--bg-2);
844	  }
845	  .landing-category-select .landing_cat_buttons > button.--active {
846	    align-items: center;
847	    border: 1px solid var(--primary-400);
