851	    flex-shrink: 0;
852	    gap: 4px;
853	    padding: 8px 16px;
854	    background-color: var(--bg-2);
855	    font-weight: 700;
856	  }
857	  .landing-category-select .landing_cat_buttons > button {
858	    border: 0;
859	    color: var(--primary);
860	    font-size: .875rem;
861	    height: 47px;
862	    margin: 0;
863	    min-width: unset !important;
864	    padding: 0 8px;
865	    position: relative;
866	  }
867	  #thread-sidebar-visible:checked ~ #sidebar-backdrop {
868	    background-color: unset !important;
869	  }
870	  .chat_bubble .actions,
871	  .editing .actions {
