  --btn-primary-color: var(--bg-0);
  --btn-group-bg: var(--bg-0);
  --nav_n_se_line: var(--yellow);
  --nav_n_im_line: var(--blue);
  --nav_n_vi_line: var(--red);
  --nav_n_ne_line: var(--violet);
  --nav_n_ma_line: var(--green);
  --secondary: var(--bg-0);
  --app-sidebar-item-border: rgba(255, 255, 255, .2);
  --app-sidebar-link: rgba(255, 255, 255, .6);
  --app-sidebar-nav-item-bg_hover: var(--yellow);
  --app-sidebar-nav-item-icon_hover: var(--bg-0);
  --result-item-title-border: var(--orange);
  --result-item-title-border_hover: var(--primary-hover);
  --result-item-title-visited-border: var(--magenta);
  --result-rank-icon-stroke_promoted: var(--fg-1);
  --result-item-highlight: var(--cyan);
  --search-result-content-text: var(--fg-1);
  --search-result-url-link: var(--green);
  --search-result-title: var(--fg-1);
  --search-result-title-hover: var(--primary-hover);
  --search-result-date-bg: var(--bg-2);
  --search-result-date-new-bg: var(--bg-0);
  --search-result-date-new: var(--cyan);
  --domain-rank-icon-color-ban: var(--red);
  --domain-rank-icon-color-lower: var(--red);
  --domain-rank-icon-color-normal: var(--red);
  --domain-rank-icon-color-higher: var(--red);
  --domain-rank-icon-color-boosted: var(--red);
  --domain-rank-icon-color-trackers: var(--orange);
  --domain-rank-icon-color-trackers-hover: var(--br-red);
  --domain-rank-icon-color-scam: var(--orange);
  --domain-rank-icon-color-scam-hover: var(--br-red);
  --ranked-box-connection-secure: var(--green);
  --ranked-box-connection-insecure: var(--red);
  --ranked-box-tracker-desc-danger: var(--red);
  --ranked-box-tracker-desc-clear: var(--green);
  --inline-header-title: var(--fg-1);
  --inline-widget-bg: var(--bg-2);
  --inline-widget-hover-bg: var(--grey-1);
  --inline-header-border: var(--red);
  --inline-domain-tag-bg: var(--magenta);
  --related-item-bg: var(--bg-2);
  --related-item-hover-bg: var(--grey-1);
  --video-item-bg: var(--bg-2);
  --auto-sugg-bg_hover: var(--bg-2);
  --provider-breakdown_server: var(--cyan);
  --provider-breakdown_client: var(--orange);
  --provider-breakdown_speed1: var(--yellow);
  --provider-breakdown_speed2: var(--red);
  --provider-breakdown_speed3: var(--red);
  --widget-progress_bar: var(--fg-1);
  --translate-fc_icon: var(--fg-1);
  --rating-star_background: var(--grey-1);
  --wiki-content-links: var(--fg-1);
  --m_sri_gap_color: var(--grey-1);
  --ai_chat_buble_a_bg: var(--kagi-accent);
  --ai_chat_buble_q_bg: var(--app-bg);
  --ai_chat_buble_dd_q_bg: var(--kagi-accent);
  --ai_chat_buble_dd_a_bg: var(--grey-1);
  --ai_chat_buble_a_text: var(--app-text);
  --ai_chat_buble_q_text: var(--app-text);
  --ai_chat_input_text: var(--app-text);
  --ai_chat_input_button: var(--cyan);
  --doggo-color-1: var(--fg-1);
  --doggo-bg-color: var(--app-bg);
  --doggo-stroke-color: var(--br-red);
  --landing-page-clouds-opacity: 1;
  --quick-search-bg: var(--fg-1);
  --quick-search-icon: var(--bg-0);
  --app-logo: var(--fg-1);
  --app-logo-bg: var(--yellow);
  --filters-clear-btn-icon: var(--br-red);
  --filter-dd-bg: var(--grey-2);
  --k-tooltip-bg: var(--background-color-sky);
  --k-tooltip-text: var(--fg-1);
  --dd-hover-bg: var(--violet);
  --dd-hover-color: var(--fg-1);
  --dd-list-input-bg: var(--input-bg);
  --not-found-bubble-bg: var(--grey-1);
