  --site_info_bottom_bg: var(--kagi-accent);
  --code-bg: var(--bg-0);
  --code-border: var(--dim);
  --code-k: var(--violet);
  --code-s: var(--green);
  --code-cm-c1: var(--br-red);
  --code-n: var(--violet);
  --code-p: var(--fg-1);
