  --onb_theme_calm_blue_preview_box: none;
  --onb_theme_royal_blue_preview_box: none;
  --onb_theme_moon_dark_preview_box: none;
  --image_brightness: 100%;
}

.theme_moon_dark {
  --bg-0: #103c48;
  --bg-1: #184956;
  --bg-2: #2d5b69;
  --dim: #72898f;
  --fg-0: #adbcbc;
  --fg-1: #cad8d9;
  --red: #fa5750;
  --green: #75b938;
  --yellow: #dbb32d;
  --blue: #4695f7;
  --magenta: #f275be;
  --cyan: #41c7b9;
  --orange: #ed8649;
  --violet: #af88eb;
  --br-red: #ff665c;
  --br-green: #84c747;
  --br-yellow: #ebc13d;
  --br-blue: #58a3ff;
  --br-magenta: #ff84cd;
  --br-cyan: #53d6c7;
  --br-orange: #fd9456;
  --br-violet: #bd96fa;
  --grey-1: #446a76;
  --grey-2: #5b7a82;
  --grey-3: #869a9e;
  --grey-4: #99abad;
  --color-scheme: dark;
  --app-bg: var(--bg-0);
  --app-text: var(--fg-1);
  --header-bg: var(--app-bg);
  --inline-widget-bg: var(--bg-2);
  --inline-widget-hover-bg: var(--grey-1);
  --btn-primary-bg: var(--fg-1);
  --btn-primary-text: var(--bg-0);
  --checkbox-bg: var(--yellow);
  --checkbox-check: var(--bg-0);
  --onboarding_theme_options_dark_visibility: flex;
  --onboarding_theme_options_light_visibility: none;
  --onb_theme_light_preview_box: none;
  --onb_theme_moon_dark_preview_box: flex;
  --k-tooltip-bg: var(--background-color-sky);
  --k-tooltip-text: var(--fg-1);
}

@media (prefers-color-scheme: dark) {
  .theme_moon_dark_conditional {
    --bg-0: #103c48;
    --bg-1: #184956;
    --bg-2: #2d5b69;
    --dim: #72898f;
    --fg-0: #adbcbc;
    --fg-1: #cad8d9;
    --red: #fa5750;
    --green: #75b938;
    --yellow: #dbb32d;
    --blue: #4695f7;
    --magenta: #f275be;
    --cyan: #41c7b9;
    --orange: #ed8649;
    --violet: #af88eb;
    --br-red: #ff665c;
    --br-green: #84c747;
    --br-yellow: #ebc13d;
    --br-blue: #58a3ff;
    --br-magenta: #ff84cd;
    --br-cyan: #53d6c7;
    --br-orange: #fd9456;
    --br-violet: #bd96fa;
    --grey-1: #446a76;
    --grey-2: #5b7a82;
    --grey-3: #869a9e;
    --grey-4: #99abad;
    --color-scheme: dark;
    --app-bg: var(--bg-0);
    --app-text: var(--fg-1);
    --header-bg: var(--app-bg);
    --inline-widget-bg: var(--bg-2);
    --inline-widget-hover-bg: var(--grey-1);
    --btn-primary-bg: var(--fg-1);
    --btn-primary-text: var(--bg-0);
    --checkbox-bg: var(--yellow);
    --checkbox-check: var(--bg-0);
    --onboarding_theme_options_dark_visibility: flex;
    --onboarding_theme_options_light_visibility: none;
    --onb_theme_light_preview_box: none;
    --onb_theme_moon_dark_preview_box: flex;
    --k-tooltip-bg: var(--background-color-sky);
    --k-tooltip-text: var(--fg-1);
  }
}

/* Global Styles */

/* Hide landing category items */
.landing-category-select .landing_cat_buttons > .nav-item.n_se::after,
.landing-category-select .landing_cat_buttons > .nav-item.n_im::after,
.landing-category-select .landing_cat_buttons > .nav-item.n_vi::after,
.landing-category-select .landing_cat_buttons > .nav-item.n_ne::after,
.landing-category-select .landing_cat_buttons > .nav-item.n_ma::after {
  display: none;
}

/* Toggle Switch */
.k_ui_toggle_switch input:checked ~ .k_ui_toggle_switch_bar:after {
  background-color: var(--bg-2);
  border-color: var(--grey-1);
}

.k_ui_toggle_switch input:checked ~ .k_ui_toggle_switch_bar {
  background: var(--green);
  border-color: var(--primary-25);
}
.k_ui_toggle_switch.--enabled .k_ui_toggle_switch_bar {
  background: var(--primary-g-6);
}
.k_ui_toggle_switch.--mini .k_ui_toggle_switch_bar {
  --border-color: var(--primary-g-6);
}
.k_ui_toggle_switch.--enabled .k_ui_toggle_switch_bar:after {
