._0_d_info_ranking.k_ui_btn_group #domain_rank_boost:checked + .k_ui_btn {
  background-color: var(--br-blue);
  color: var(--bg-0);
}

.ranking-note {
  background-color: var(--bg-2);
  color: var(--fg-1);
}
